      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'bot', n."id"::text, 'owner', n."owner_id"::text, jsonb_build_object('column', 'owner_id', 'was', o."owner_id"), nullif(current_setting('authz_ctx.reason', true), '')
